// ============================================================================
// CHRISTIAN RELIGIOUS EDUCATION GRADE 5: skills, prerequisites and the misconception library (authoring source).
// Written offline by Claude (12 Nov 2026), no model call. Everything here is DRAFT until a CRE teacher who knows the
// school's tradition reviews it (docs/qa/cre-g5-review-*.md lists what to check).
// scripts/build-cre-g5.mjs merges it into curriculum/cre/g5.json (HOREB owns that file; the KICD rubrics are never touched)
// and writes the in-app map. Keys: 'THE_BI.NOAH_AND_HIS_SONS' = the sub-strand CRE.G5.THE_BI.NOAH_AND_HIS_SONS.
//
// Rules this file follows (owner's brief): Bible references are the ones the KICD design itself gives, and every fact asked is
// stated in that passage; no denominational claims (no numbering of the Ten Commandments, no teaching on how Holy
// Communion works or how baptism is done); values are for teacher judgement, never scored; Islamic and Hindu RE are not loaded.
// Skill codes start CRES (four capitals the registry needs); the official outcome codes stay CRE.G5.
// ============================================================================
export const TO_CONFIRM = 'common learner error; to confirm by a CRE teacher';
export const FROM_TEXT = 'The learner reads the passage loosely or mixes it with a similar Bible story (to confirm by a CRE teacher)';

// S(sub, id, name, outcomes, mastery, questionForms, prerequisites, thinking)
const S = (sub, id, name, outcomes, mastery, forms, pre = [], thinking = ['recall']) => ({ sub, id, name, outcomes, mastery, forms, pre, thinking });
// M(skill, code, error, question, wrong, right, cause, help, feedback, source)
const M = (skill, code, error, question, wrong, right, cause, help, feedback, source = TO_CONFIRM) => ({ skill, code, error, example: { question, wrong_answer: wrong, correct_answer: right }, cause, help, feedback, source });

